/*
 * A005224  T is the first, fourth, eleventh, ... letter in this sentence, not
 *          counting spaces or commas (Aronson's sequence).
 * https://oeis.org/A005224
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, word, nice
 * Formula:   generated by building Aronson's sentence "T is the first,
 *            fourth, eleventh, ..." letter by letter (spaces, hyphens and
 *            commas not counted, American number names without "and"); a(n)
 *            is the position of the n-th letter 't'. Word k after "Tisthe" is
 *            the ordinal of a(k)
 * Range:     u8 n <= 51, u16 n <= 7754, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static uint64_t *g_pos = NULL;   /* positions of t's found so far */
static idx_t g_cnt = 0;          /* number of t's found */
static idx_t g_cap = 0;
static uint64_t g_len = 0;       /* letters written so far */
static idx_t g_next = 0;         /* index (0-based) of next ordinal to write */
static int g_init = 0;

static const char *card_small[] = {"", "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen"};
static const char *ord_small[] = {"", "first", "second", "third", "fourth", "fifth", "sixth",
    "seventh", "eighth", "ninth", "tenth", "eleventh", "twelfth", "thirteenth", "fourteenth",
    "fifteenth", "sixteenth", "seventeenth", "eighteenth", "nineteenth"};
static const char *card_tens[] = {"", "", "twenty", "thirty", "forty", "fifty", "sixty",
    "seventy", "eighty", "ninety"};
static const char *ord_tens[] = {"", "", "twentieth", "thirtieth", "fortieth", "fiftieth",
    "sixtieth", "seventieth", "eightieth", "ninetieth"};

static void card_below_1000(char *buf, uint64_t n) {
    if (n >= 100) {
        strcat(buf, card_small[n / 100]);
        strcat(buf, "hundred");
        n %= 100;
    }
    if (n >= 20) {
        strcat(buf, card_tens[n / 10]);
        n %= 10;
    }
    if (n > 0) strcat(buf, card_small[n]);
}

static void card_full(char *buf, uint64_t n) {
    static const uint64_t scales[] = {1000000000000ULL, 1000000000ULL, 1000000ULL, 1000ULL};
    static const char *names[] = {"trillion", "billion", "million", "thousand"};
    int i;
    for (i = 0; i < 4; i++) {
        if (n >= scales[i]) {
            card_below_1000(buf, (n / scales[i]) % 1000);
            strcat(buf, names[i]);
            n %= scales[i];
        }
    }
    card_below_1000(buf, n);
}

static void ordinal(char *buf, uint64_t n) {
    static const uint64_t scales[] = {1000000000000ULL, 1000000000ULL, 1000000ULL, 1000ULL, 100ULL};
    static const char *names[] = {"trillion", "billion", "million", "thousand", "hundred"};
    int i;
    for (i = 0; i < 5; i++) {
        if (n >= scales[i]) {
            uint64_t hi = n / scales[i], r = n % scales[i];
            card_full(buf, hi);
            strcat(buf, names[i]);
            if (r == 0) {
                strcat(buf, "th");
            } else {
                ordinal(buf, r);
            }
            return;
        }
    }
    if (n < 20) {
        strcat(buf, ord_small[n]);
    } else if (n % 10 == 0) {
        strcat(buf, ord_tens[n / 10]);
    } else {
        strcat(buf, card_tens[n / 10]);
        strcat(buf, ord_small[n % 10]);
    }
}

static void push_pos(uint64_t p) {
    if (g_cnt >= g_cap) {
        idx_t nc = g_cap ? g_cap * 2 : 1024;
        g_pos = (uint64_t *)realloc(g_pos, (size_t)nc * sizeof(uint64_t));
        g_cap = nc;
    }
    g_pos[g_cnt++] = p;
}

static void scan_word(const char *w) {
    size_t i;
    for (i = 0; w[i]; i++) {
        g_len++;
        if (w[i] == 't' || w[i] == 'T') push_pos(g_len);
    }
}

static void extend(idx_t n) {
    if (!g_init) {
        g_init = 1;
        scan_word("Tisthe");
    }
    while (g_cnt < n) {
        char buf[512];
        buf[0] = '\0';
        ordinal(buf, g_pos[g_next]);
        g_next++;
        scan_word(buf);
    }
}

seq_t a(idx_t n) {
    extend(n);
    return (seq_t)g_pos[n - 1];
}
